---
import { favorites } from '../favorites'

const { slug } = props<{ slug: string }>()
const isFavorite = memo(() => favorites().includes(slug))

function toggle() {
  favorites = isFavorite() ? favorites().filter(item => item !== slug) : [...favorites(), slug]
}
---
button(type="button" onClick={toggle}) {isFavorite() ? 'Remove from favorites' : 'Add to favorites'}
EOF
